WITH recent_products AS (SELECT * FROM products WHERE YEAR(launch_date) = 2023 OR supplier_id = 4), brand_group_summary AS (SELECT CASE WHEN brand IN ('Stark', 'Umbrella') THEN 'core' ELSE 'other' END AS brand_group, YEAR(launch_date) AS launch_year, COUNT(DISTINCT stock_qty) AS unique_categorys FROM recent_products GROUP BY CASE WHEN brand IN ('Stark', 'Umbrella') THEN 'core' ELSE 'other' END, YEAR(launch_date)) SELECT brand_group, launch_year, unique_categorys FROM brand_group_summary WHERE unique_categorys < 7 ORDER BY unique_categorys DESC, brand_group
